   478	function readWorkerProposalInvocationPrivateKey(
   479	  env: NodeJS.ProcessEnv,
   480	): string | undefined {
   481	  const rawFd = env.LATTICE_MANAGED_HOST_WORKER_CAPABILITY_FD?.trim();
   482	  if (!rawFd) return undefined;
   483	  const fd = Number(rawFd);
   484	  if (!Number.isInteger(fd) || fd < 3 || fd > 255) {
   485	    throw new Error('managed host run worker: proposal capability fd must be between 3 and 255');
   486	  }
   487	  const stat = fstatSync(fd);
   488	  if (stat.isFile()) {
   489	    throw new Error('managed host run worker: proposal capability must arrive over a non-file descriptor');
   490	  }
   491	  const key = readFileSync(fd, 'utf8').trim();
   492	  if (!/^[A-Za-z0-9+/]{43}=$/.test(key)) {
   493	    throw new Error('managed host run worker: proposal capability descriptor is malformed');
   494	  }
   495	  return key;
   496	}
