   524	
   525	function canonicalJson(value: unknown): string {
   526	  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(',')}]`;
   527	  if (value && typeof value === 'object') {
   528	    const entries = Object.entries(value as Record<string, unknown>)
   529	      .filter(([, item]) => item !== undefined)
   530	      .sort(([left], [right]) => left.localeCompare(right));
   531	    return `{${entries.map(([key, item]) => `${JSON.stringify(key)}:${canonicalJson(item)}`).join(',')}}`;
   532	  }
   533	  return JSON.stringify(value);
   534	}
