   569	/**
   570	 * Remove only the detached cross-host snapshot shape created by the managed
   571	 * adapter. The canonical tmp boundary is checked before either git metadata or
   572	 * filesystem state is touched, so a persisted caller-controlled cwd cannot
   573	 * turn retention GC into an arbitrary deletion primitive.
   574	 */
   575	export function cleanupManagedCrossHostReviewWorktree(gitCwd: string, worktree: string): void {
   576	  const parent = dirname(worktree);
   577	  if (basename(worktree) !== 'worktree'
   578	    || !basename(parent).startsWith('lattice-xhr-review-')
   579	    || dirname(parent) !== tmpdir()) {
   580	    throw new Error(`managed host run: cross-host review snapshot is outside the canonical temporary boundary: ${worktree}`);
   581	  }
   582	  if (!existsSync(worktree)) {
   583	    const registeredWorktrees = execFileSync('git', ['worktree', 'list', '--porcelain'], {
   584	      cwd: gitCwd,
   585	      encoding: 'utf8',
   586	      stdio: ['ignore', 'pipe', 'pipe'],
   587	      maxBuffer: 8 * 1024 * 1024,
   588	    });
   589	    const registered = registeredWorktrees
   590	      .split('\n')
   591	      .some(line => line === `worktree ${resolve(worktree)}`);
   592	    if (!registered) {
   593	      rmSync(parent, { recursive: true, force: true });
   594	      return;
   595	    }
   596	  }
   597	  // Git administration is authoritative for a registered worktree. If this
   598	  // mutation fails, retain the filesystem snapshot and surface the error to GC
   599	  // diagnostics; deleting only the directory would strand hidden registration
   600	  // state while falsely reporting successful cleanup.
   601	  execFileSync('git', ['worktree', 'remove', '--force', worktree], {
   602	    cwd: gitCwd,
   603	    encoding: 'utf8',
   604	    stdio: ['ignore', 'pipe', 'pipe'],
   605	    maxBuffer: 8 * 1024 * 1024,
   606	  });
   607	  rmSync(parent, { recursive: true, force: true });
   608	}
