   636	const managedReconcileQueues = new Map<string, Promise<void>>();
   637	
   638	async function withManagedReconcileLock<T>(
   639	  paths: ManagedHostRunPaths,
   640	  fn: () => Promise<T>,
   641	): Promise<T> {
   642	  const previous = managedReconcileQueues.get(paths.reconcileLock) ?? Promise.resolve();
   643	  let releaseTurn!: () => void;
   644	  const turn = new Promise<void>(resolve => { releaseTurn = resolve; });
   645	  const tail = previous.then(() => turn);
   646	  managedReconcileQueues.set(paths.reconcileLock, tail);
   647	  await previous;
   648	  let lock: ReturnType<typeof acquireMkdirLock> | null = null;
   649	  try {
