  1943	    return AMBIGUOUS_PROCESS_CLEANUP;
  1944	  }
  1945	  let rows = ops.rows(identity.pgid);
  1946	  if (rows === null) return AMBIGUOUS_PROCESS_CLEANUP;
  1947	  if (rows.length === 0) return REAPED_WITHOUT_SIGNAL;
  1948	  if (!canSignalObservedManagedProviderGroup(identity, rows)) return AMBIGUOUS_PROCESS_CLEANUP;
