  1960	  if (rows.length === 0) return { termSent, killSent: false, reaped: true, residualProcessGroup: false };
  1961	  if (!canSignalObservedManagedProviderGroup(identity, rows)) {
  1962	    return { termSent, killSent: false, reaped: false, residualProcessGroup: true };
  1963	  }
  1964	  let killSent = false;
  1965	  try {
  1966	    ops.signal(identity.pgid, 'SIGKILL');
  1967	    killSent = true;
  1968	  } catch (error) {
  1969	    if ((error as NodeJS.ErrnoException).code !== 'ESRCH') {
  1970	      return { termSent, killSent, reaped: false, residualProcessGroup: true };
  1971	    }
