   946	  const allowed = new Set(['desc', 'severity', 'category', 'files', 'evidenceState', 'uncertaintyReason']);
   947	  if (Object.keys(value).some(key => !allowed.has(key))) return false;
   948	  if (typeof value.desc !== 'string' || value.desc.trim().length === 0) return false;
   949	  if (!['critical', 'high', 'medium', 'low'].includes(String(value.severity))) return false;
   950	  if (!['happy', 'edge', 'adversarial', 'missing'].includes(String(value.category))) return false;
   951	  if (value.files !== undefined
   952	    && (!isStringArray(value.files) || value.files.some(file => file.trim().length === 0))) return false;
   953	  if (value.evidenceState !== undefined
   954	    && value.evidenceState !== 'suspected'
   955	    && value.evidenceState !== 'verified') return false;
   956	  if (value.evidenceState === 'suspected') {
   957	    if (typeof value.uncertaintyReason !== 'string' || value.uncertaintyReason.trim().length === 0) return false;
   958	  } else if (value.uncertaintyReason !== undefined) {
   959	    return false;
   960	  }
   961	  return true;
   962	}
