   972	  const trimmed = text.trim();
   973	  let parsed: unknown;
   974	  try {
   975	    parsed = JSON.parse(trimmed);
   976	  } catch {
   977	    return trimmed.includes(MANAGED_REVIEW_FINAL_PROPOSAL_SCHEMA_VERSION)
   978	      ? { kind: 'malformed' }
   979	      : { kind: 'ordinary' };
   980	  }
   981	  if (!isPlainRecord(parsed)) return { kind: 'ordinary' };
   982	  if (parsed.schemaVersion !== MANAGED_REVIEW_FINAL_PROPOSAL_SCHEMA_VERSION) {
   983	    return trimmed.includes(MANAGED_REVIEW_FINAL_PROPOSAL_SCHEMA_VERSION)
   984	      ? { kind: 'malformed' }
   985	      : { kind: 'ordinary' };
   986	  }
   987	
   988	  const conclusion = parsed.conclusion;
   989	  const allowed = new Set([
   990	    'schemaVersion', 'storyId', 'providerAgent', 'lane', 'reviewRunId', 'conclusion',
   991	    'readManifest', 'readLog', 'readDiagnostics', 'note', 'findings',
   992	  ]);
   993	  const readManifest = parsed.readManifest;
   994	  const validReadManifest = isPlainRecord(readManifest)
   995	    && isStringArray(readManifest.filesReadFully)
   996	    && isStringArray(readManifest.filesTriagedByName)
   997	    && (readManifest.scanEscalationReason === null || typeof readManifest.scanEscalationReason === 'string')
