  1005	      && Array.isArray(parsed.findings)
  1006	      && parsed.findings.length > 0
  1007	      && parsed.findings.every(isStrictManagedReviewFindingProposal)
  1008	      && (parsed.note === undefined || (typeof parsed.note === 'string' && parsed.note.trim().length > 0));
