    98	/**
    99	 * One late-error guard per physical stream. A capped write can still emit EPIPE
   100	 * after its foreground command returns; keeping the per-run listener would grow
   101	 * without bound when a stream never settles. This shared guard is reference
   102	 * counted by pending writes, so it contains that late event while retaining at
   103	 * most one listener for any stream and disappears once the final write settles.
   104	 */
   105	const lateStreamErrorGuards = new WeakMap<HostRunOutputStream, {
   106	  pending: number;
   107	  listener: (error: Error) => void;
   108	}>();
   109	
   110	function retainLateStreamErrorContainment(stream: HostRunOutputStream): () => void {
   111	  let guard = lateStreamErrorGuards.get(stream);
   112	  if (!guard) {
   113	    guard = { pending: 0, listener: () => { /* late EPIPE is intentionally contained */ } };
   114	    lateStreamErrorGuards.set(stream, guard);
   115	    stream.on('error', guard.listener);
   116	  }
   117	  guard.pending += 1;
   118	  let released = false;
   119	  return () => {
   120	    if (released) return;
   121	    released = true;
   122	    const current = lateStreamErrorGuards.get(stream);
   123	    if (!current) return;
   124	    current.pending -= 1;
   125	    if (current.pending <= 0) {
   126	      stream.removeListener('error', current.listener);
   127	      lateStreamErrorGuards.delete(stream);
   128	    }
   129	  };
   130	}
