    29	/** Sign a single finding to prevent main agent from faking reviewer findings */
    30	export function signFinding(
    31	  storyId: string,
    32	  id: string,
    33	  desc: string,
    34	  severity: string,
    35	  timestamp: string,
    36	  reviewRound: string,
    37	  reviewRunId = '',
    38	  readManifest?: ReviewerReadManifest,
    39	  readLog?: ReviewerReadLogEvidence,
    40	  readDiagnostics?: ReviewerReadDiagnostic[],
    41	  gapLogBinding?: GapLogProvenanceBinding,
    42	  managedEvidenceBinding?: ManagedReviewEvidenceBinding,
    43	  nativeEvidenceBinding?: NativeReviewEvidenceBinding,
    44	  nativeFindingSemantics?: {
    45	    category: string;
    46	    evidenceState: string | null;
    47	    uncertaintyReason: string | null;
    48	    files: string[];
    49	    /** Present only for newer native records; omit preserves v6 compatibility. */
    50	    disprovenEvidence?: DisprovenEvidence;
    51	  },
    52	): string {
    53	  if (managedEvidenceBinding !== undefined && nativeEvidenceBinding !== undefined) {
    54	    throw new Error('signFinding: managed and native evidence bindings are mutually exclusive');
    55	  }
    56	  if (nativeEvidenceBinding !== undefined) {
    57	    if (!nativeFindingSemantics || nativeFindingSemantics.category.trim().length === 0) {
    58	      throw new Error('signFinding: native evidence requires exact finding semantics');
    59	    }
    60	    return digestCanonicalJson({
    61	      version: 6,
    62	      salt: FINDING_SALT,
    63	      storyId,
    64	      id,
    65	      desc,
    66	      severity,
    67	      timestamp,
    68	      reviewRound,
    69	      reviewRunId,
    70	      nativeEvidenceBinding,
    71	      nativeFindingSemantics,
    72	      ...(readManifest !== undefined ? { readManifest: normalizeReviewerReadManifest(readManifest) } : {}),
    73	      ...(readLog !== undefined ? { readLog: normalizeReviewerReadLogEvidence(readLog) } : {}),
    74	      ...(readDiagnostics !== undefined ? { readDiagnostics: normalizeReviewerReadDiagnostics(readDiagnostics) } : {}),
    75	    });
    76	  }
    77	  if (managedEvidenceBinding !== undefined) {
    78	    return digestCanonicalJson({
    79	      version: 4,
    80	      salt: FINDING_SALT,
    81	      storyId,
    82	      id,
    83	      desc,
    84	      severity,
    85	      timestamp,
    86	      reviewRound,
    87	      reviewRunId,
    88	      managedEvidenceBinding,
    89	      ...(readManifest !== undefined ? { readManifest: normalizeReviewerReadManifest(readManifest) } : {}),
    90	      ...(readLog !== undefined ? { readLog: normalizeReviewerReadLogEvidence(readLog) } : {}),
    91	      ...(readDiagnostics !== undefined ? { readDiagnostics: normalizeReviewerReadDiagnostics(readDiagnostics) } : {}),
    92	    });
    93	  }
    94	  if (gapLogBinding !== undefined) {
    95	    return digestCanonicalJson({
    96	      version: 3,
    97	      salt: FINDING_SALT,
    98	      storyId,
    99	      id,
   100	      desc,
   101	      severity,
   102	      timestamp,
   103	      reviewRound,
   104	      reviewRunId,
   105	      gapLogBinding,
   106	    });
   107	  }
   108	  if (readManifest !== undefined || readLog !== undefined || readDiagnostics !== undefined) {
   109	    return digestCanonicalJson({
   110	      version: 2,
   111	      salt: FINDING_SALT,
   112	      storyId,
   113	      id,
   114	      desc,
   115	      severity,
   116	      timestamp,
   117	      reviewRound,
   118	      reviewRunId,
   119	      ...(readManifest !== undefined ? { readManifest: normalizeReviewerReadManifest(readManifest) } : {}),
   120	      ...(readLog !== undefined ? { readLog: normalizeReviewerReadLogEvidence(readLog) } : {}),
   121	      ...(readDiagnostics !== undefined ? { readDiagnostics: normalizeReviewerReadDiagnostics(readDiagnostics) } : {}),
   122	    });
   123	  }
