   127	/** Verify finding signature (compatible with old and new formats) */
   128	export function verifyFinding(
   129	  storyId: string,
   130	  f: {
   131	    id: string;
   132	    desc: string;
   133	    severity: string;
   134	    createdAt?: string;
   135	    _hash?: string;
   136	    reviewRound?: string;
   137	    reviewRunId?: string;
   138	    readManifest?: ReviewerReadManifest;
   139	    readLog?: ReviewerReadLogEvidence;
   140	    readDiagnostics?: ReviewerReadDiagnostic[];
   141	    gapLogBinding?: GapLogProvenanceBinding;
   142	    managedEvidenceBinding?: ManagedReviewEvidenceBinding;
   143	    nativeEvidenceBinding?: NativeReviewEvidenceBinding;
   144	    category?: string;
   145	    evidenceState?: string;
   146	    uncertaintyReason?: string;
   147	    files?: string[];
   148	    disprovenEvidence?: DisprovenEvidence;
   149	  },
   150	): boolean {
   151	  if (!f._hash || !f.createdAt) return false;
   152	  const reviewRunId = f.reviewRunId?.trim() || '';
   153	  if (f.managedEvidenceBinding !== undefined && f.nativeEvidenceBinding !== undefined) return false;
   154	  if (f.nativeEvidenceBinding !== undefined) {
   155	    try {
   156	      return f._hash === signFinding(
   157	        storyId,
   158	        f.id,
   159	        f.desc,
   160	        f.severity,
   161	        f.createdAt,
   162	        f.reviewRound || '',
   163	        reviewRunId,
   164	        f.readManifest,
   165	        f.readLog,
   166	        f.readDiagnostics,
   167	        undefined,
   168	        undefined,
   169	        f.nativeEvidenceBinding,
   170	        {
   171	          category: f.category ?? '',
   172	          evidenceState: f.evidenceState ?? null,
   173	          uncertaintyReason: f.uncertaintyReason ?? null,
   174	          files: f.files ?? [],
   175	          ...(f.disprovenEvidence !== undefined ? { disprovenEvidence: f.disprovenEvidence } : {}),
   176	        },
   177	      );
   178	    } catch {
   179	      return false;
   180	    }
   181	  }
   182	  if (f.managedEvidenceBinding !== undefined) {
   183	    try {
   184	      return f._hash === signFinding(
   185	        storyId,
   186	        f.id,
   187	        f.desc,
   188	        f.severity,
   189	        f.createdAt,
   190	        f.reviewRound || '',
   191	        reviewRunId,
   192	        f.readManifest,
   193	        f.readLog,
   194	        f.readDiagnostics,
   195	        undefined,
   196	        f.managedEvidenceBinding,
   197	      );
   198	    } catch {
   199	      return false;
   200	    }
   201	  }
   202	  if (f.gapLogBinding !== undefined) {
   203	    try {
   204	      return f._hash === signFinding(
   205	        storyId,
   206	        f.id,
   207	        f.desc,
   208	        f.severity,
   209	        f.createdAt,
   210	        f.reviewRound || '',
   211	        reviewRunId,
   212	        undefined,
   213	        undefined,
   214	        undefined,
   215	        f.gapLogBinding,
   216	      );
   217	    } catch {
   218	      return false;
   219	    }
   220	  }
   221	  if (f.readManifest !== undefined || f.readLog !== undefined || f.readDiagnostics !== undefined) {
   222	    try {
   223	      return f._hash === signFinding(
   224	        storyId,
   225	        f.id,
   226	        f.desc,
   227	        f.severity,
   228	        f.createdAt,
   229	        f.reviewRound || '',
   230	        reviewRunId,
   231	        f.readManifest,
   232	        f.readLog,
   233	        f.readDiagnostics,
   234	      );
   235	    } catch {
   236	      return false;
   237	    }
   238	  }
   239	  if (reviewRunId) {
   240	    return f._hash === signFinding(storyId, f.id, f.desc, f.severity, f.createdAt, f.reviewRound || '', reviewRunId);
   241	  }
   242	  // Fallback: legacy format with reviewRound but without reviewRunId
   243	  const newExpected = signFinding(storyId, f.id, f.desc, f.severity, f.createdAt, f.reviewRound || '');
   244	  if (f._hash === newExpected) return true;
