   276	function gitCommonDir(gitCwd: string): string {
   277	  const raw = execFileSync('git', ['rev-parse', '--git-common-dir'], {
   278	    cwd: gitCwd,
   279	    encoding: 'utf8',
   280	    stdio: ['pipe', 'pipe', 'pipe'],
   281	  }).trim();
   282	  return isAbsolute(raw) ? raw : resolve(gitCwd, raw);
   283	}
   284	
   285	function receiptKeyPath(gitCwd: string): string {
   286	  return join(gitCommonDir(gitCwd), 'lattice-gap-log-provenance.key');
   287	}
   288	
   289	function receiptPayload(receipt: Omit<GapLogProvenanceReceipt, 'integrityHash'>): string {
   290	  return JSON.stringify(receipt);
   291	}
   292	
   293	function expectedReceiptHash(gitCwd: string, receipt: Omit<GapLogProvenanceReceipt, 'integrityHash'>): string | null {
   294	  const keyPath = receiptKeyPath(gitCwd);
   295	  if (!existsSync(keyPath)) return null;
   296	  return createHmac('sha256', readFileSync(keyPath)).update(receiptPayload(receipt)).digest('hex');
   297	}
